## Koncepcja

- **Format:** 1080×1920 (9:16), 8 s, cichy MP4.
- **Styl:** izometryczny rysunek liniowy (Hairline). Linia ma 2,2 px, w ciemnych odcieniach szarości na płaskim tle, bez poświaty, cieni i gradientów.
- **Szafka:** komoda z czterema szufladami o różnych wysokościach, cokołem i blatem z lekkim zwisem. Każda szuflada ma przód i rączkę.
- **Jedyny akcent:** jasna kreska na szufladzie, która aktualnie się wysuwa. W spoczynku świeci druga od góry.
- **Napis** pod rysunkiem, poza nim: „szafka”, potem „szuflada 01…04”.

| Czas | Co się dzieje |
|---|---|
| 0–0,8 s | Szafka zamknięta, jasna kreska na drugiej szufladzie |
| 0,8 / 1,8 / 2,8 / 3,8 s | Szuflady wysuwają się po kolei z góry na dół i zostają otwarte. Ruch jest na sprężynie, bez ruchu liniowego |
| 3,8–6,0 s | Wszystkie cztery otwarte, trzymane |
| 6,0–7,4 s | Zamykają się od dołu, kolejno |
| 7,4–8,0 s | Spoczynek, dobry do pętli |

Przyjęte skróty:
- Sąsiednie szuflady nie reagują na wysunięcie jednej z nich, bo szuflady ruszają się niezależnie.
- Szuflady wysuwają się kolejno, a nie jedna naraz. Potraktowałem „po kolei” jako rosnącą kaskadę.

## `index.html`

Skopiuj z `skills/hyperframes-workflow/assets/hairline/` plik `hairline-kit.js` obok tego pliku.

```html
<!doctype html>
<html lang="pl">
<head>
<meta charset="UTF-8" />
<title>Szafka z szufladami</title>
<script src="hairline-kit.js"></script>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  html, body { width: 1080px; height: 1920px; overflow: hidden; background: #0e0f12; }
  #root { position: relative; width: 100%; height: 100%; background: var(--plate);
          --plate: #0e0f12; --hi: #fafafa; --edge: #a1a1aa; --mid: #52525b; --lo: #27272a; --stroke: 2.2px; }
  #art { position: absolute; inset: 0; }
  .hl-sil { fill: var(--plate); stroke: var(--edge); stroke-width: var(--stroke); stroke-linejoin: round; }
  .hl-sil.hi { stroke: var(--hi); }
  .hl-crease { fill: none; stroke: var(--mid); stroke-width: var(--stroke); stroke-linecap: round; }
  .read { position: absolute; left: 96px; bottom: 330px; font: 500 34px/1 ui-monospace, "DejaVu Sans Mono", monospace;
          letter-spacing: .04em; color: var(--edge); }
</style>
</head>
<body>
<div id="root">
  <svg id="art" viewBox="0 0 1080 1920" role="img" aria-label="Izometryczny rysunek szafki z czterema szufladami, które wysuwają się po kolei"></svg>
  <div class="read" id="read">szafka</div>
</div>
<script>
const { frame, solid, put, springAt, tourAt } = HairlineKit;
const svg = document.getElementById('art'), read = document.getElementById('read');
const K = frame(546, 900, 1.55);

const W = 300, DEP = 190, S = 120, GAP = 6, PLINTH = 26, TOP_T = 14;
const HS = [52, 60, 68, 76];                       // wysokości szuflad od góry: nierówny rytm, nie regularny rząd
const BODY_H = HS.reduce((a, b) => a + b, 0) + GAP * (HS.length + 1);

// Kolejność od tyłu do przodu: cokół, korpus, blat, potem szuflady od dołu do góry
put(svg, solid(K.P, { x: 18, y: 18, w: W - 36, d: DEP - 36, z: 0, h: PLINTH, r: 4 }));
put(svg, solid(K.P, { x: 0, y: 0, w: W, d: DEP, z: PLINTH, h: BODY_H, r: 5, inset: 2 }));
put(svg, solid(K.P, { x: -8, y: -8, w: W + 16, d: DEP + 16, z: PLINTH + BODY_H, h: TOP_T, r: 7 }));

// Plan: szuflada k (0 = górna) wysuwa się o 0,8 + k s, zamykają się od dołu od 6,0 s
const OPEN = k => 0.8 + k;
const CLOSE = k => 6.0 + (HS.length - 1 - k) * 0.14;
const TOUR = [{ t: 0, at: null }, ...HS.map((_, k) => ({ t: OPEN(k), at: k })), { t: 6.0, at: null }];
const REST_MARK = 1;                               // jedna jasna kreska w spoczynku

const drawers = [];
for (let k = HS.length - 1; k >= 0; k--) {
  let z = PLINTH + GAP;
  for (let j = k + 1; j < HS.length; j++) z += HS[j] + GAP;
  const g = document.createElementNS(HairlineKit.NS, 'g'); svg.appendChild(g);
  drawers.push({ k, z, h: HS[k], tray: put(g, { sil: '', crease: '' }), front: put(g, { sil: '', crease: '' }),
                 handle: put(g, { sil: '', crease: '' }), g,
                 changes: [{ t: OPEN(k), to: S }, { t: CLOSE(k), to: 0 }] });
}

function renderFrame(t) {
  const at = tourAt(t, TOUR);
  for (const d of drawers) {
    const s = Math.max(0, springAt(t, 0, d.changes));   // sprężyna nie wchodzi w korpus
    const open = s > 0.8;
    d.tray.g.setAttribute('display', open ? 'inline' : 'none');
    if (open) d.tray.draw(solid(K.P, { x: 12, y: DEP, w: W - 24, d: s, z: d.z + 8, h: d.h - 16, r: 3, inset: 3 }));
    d.front.draw(solid(K.P, { x: 8, y: DEP + s, w: W - 16, d: 8, z: d.z, h: d.h, r: 3, inset: 2 }));
    d.handle.draw(solid(K.P, { x: W / 2 - 35, y: DEP + s + 8, w: 70, d: 9, z: d.z + d.h / 2 - 4, h: 8, r: 4, inset: 1.5 }));
    const chosen = at === null ? d.k === REST_MARK : d.k === at;
    d.front.sil.classList.toggle('hi', chosen);
    d.handle.sil.classList.toggle('hi', chosen);
  }
  read.textContent = at === null ? 'szafka' : `szuflada ${String(at + 1).padStart(2, '0')}`;
}
window.renderFrame = renderFrame;
renderFrame(0);
</script>
</body>
</html>
```

